package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.stats.*;
final class CopulaDialog {
 record Settings(int response,int[] predictors,CopulaRegression.Model model,Bootstrap.Options bootstrap){Settings{predictors=predictors.clone();Objects.requireNonNull(model);Objects.requireNonNull(bootstrap);if(response<0||predictors.length!=model.names().size())throw new IllegalArgumentException("Copula response/predictor selection differs from model.");Set<Integer> unique=new HashSet<>();for(int column:predictors)if(column<0||column==response||!unique.add(column))throw new IllegalArgumentException("Response and unique predictors must be distinct.");}@Override public int[] predictors(){return predictors.clone();}}
 private final Dialog<Settings> dialog=new Dialog<>();private final ComboBox<String> response=new ComboBox<>();private final ListView<String> predictors=new ListView<>(),endogenous=new ListView<>();private final ComboBox<CopulaRegression.Method> method=new ComboBox<>();private final ComboBox<CopulaRegression.PlottingPosition> position=new ComboBox<>();private final ComboBox<BootstrapIntervals.Method> interval=new ComboBox<>();private final TextField samples=new TextField(),seed=new TextField(),confidence=new TextField();private final Label error=new Label();private final List<String> names;private Settings result;
 CopulaDialog(Window owner,List<String> names,Settings previous,boolean resampling){if(names.size()<2)throw new IllegalArgumentException("Import at least two variables for copula regression.");this.names=List.copyOf(names);dialog.initOwner(owner);dialog.setTitle(resampling?"Gaussian-copula regression bootstrap":"Gaussian-copula endogeneity analysis");dialog.setResizable(true);response.getItems().setAll(names);response.getSelectionModel().select(names.size()-1);for(var list:List.of(predictors,endogenous)){list.getItems().setAll(names);list.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);list.setPrefSize(310,200);}for(int j=0;j<names.size()-1;j++)predictors.getSelectionModel().select(j);endogenous.getSelectionModel().select(0);method.getItems().setAll(CopulaRegression.Method.values());method.setValue(names.size()>2?CopulaRegression.Method.TWO_STAGE_GAUSSIAN:CopulaRegression.Method.ORIGINAL_GAUSSIAN);position.getItems().setAll(CopulaRegression.PlottingPosition.values());position.setValue(CopulaRegression.PlottingPosition.WEIBULL);var boot=previous==null?new Bootstrap.Options(5000,42,.95):previous.bootstrap();samples.setText(Integer.toString(boot.samples()));seed.setText(Long.toString(boot.seed()));confidence.setText(Double.toString(boot.confidence()));interval.getItems().setAll(BootstrapIntervals.Method.PERCENTILE,BootstrapIntervals.Method.BCA);interval.setValue(boot.interval()==BootstrapIntervals.Method.BCA?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE);
  if(previous!=null){validate(previous,names);response.getSelectionModel().select(previous.response());predictors.getSelectionModel().clearSelection();endogenous.getSelectionModel().clearSelection();for(int column:previous.predictors())predictors.getSelectionModel().select(column);for(int local:previous.model().endogenous())endogenous.getSelectionModel().select(previous.predictors()[local]);method.setValue(previous.model().method());position.setValue(previous.model().plottingPosition());}
  Label guidance=UiAppearance.label("Use continuous endogenous variables. The two-stage Gaussian method (2sCOPE) also transforms continuous exogenous controls. Categorical/ordinal endogenous data require another method. Identification and Gaussian-copula/structural-error assumptions need substantive justification. Bootstrap re-estimates ranks and both stages in every sample; no causal verdict is automatic.");guidance.setWrapText(true);Label selection=UiAppearance.label("Ctrl-click for multiple selections. Every endogenous variable must also be selected as a predictor. Remaining predictors are exogenous controls.");selection.setWrapText(true);GridPane grid=new GridPane();grid.setHgap(14);grid.setVgap(8);grid.addRow(0,UiAppearance.label("Outcome"),response);grid.addRow(1,UiAppearance.label("Correction method"),method);grid.addRow(2,UiAppearance.label("Rank plotting position"),position);grid.addRow(3,UiAppearance.label("Predictors"),UiAppearance.label("Endogenous subset"));grid.addRow(4,predictors,endogenous);grid.addRow(5,UiAppearance.label("Bootstrap attempts"),samples);grid.addRow(6,UiAppearance.label("Seed"),seed);grid.addRow(7,UiAppearance.label("Confidence (0–1)"),confidence);grid.addRow(8,UiAppearance.label("Standard case interval"),interval);for(var node:List.of(samples,seed,confidence,interval))node.setDisable(!resampling);error.setWrapText(true);error.setStyle("-fx-text-fill:#a02020");VBox content=new VBox(10,guidance,selection,grid,UiAppearance.label("WEIBULL: average rank/(n+1); HAZEN: (average rank−0.5)/n. Ties use midranks."),error);content.setPadding(new Insets(12));content.setPrefWidth(760);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(650);dialog.getDialogPane().setContent(scroll);ButtonType run=new ButtonType(resampling?"Bootstrap":"Calculate",ButtonBar.ButtonData.OK_DONE);dialog.getDialogPane().getButtonTypes().addAll(run,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(run).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{result=resolve();error.setText("");}catch(RuntimeException problem){error.setText(problem.getMessage());event.consume();}});dialog.setResultConverter(button->button==run?result:null);
 }
 static void validate(Settings settings,List<String> names){if(settings.response()>=names.size())throw new IllegalArgumentException("Copula response is out of range.");int[] columns=settings.predictors();for(int j=0;j<columns.length;j++)if(columns[j]>=names.size()||!names.get(columns[j]).equals(settings.model().names().get(j)))throw new IllegalArgumentException("Copula predictor names/indices differ from the dataset.");}
 private Settings resolve(){int y=response.getSelectionModel().getSelectedIndex();int[] columns=predictors.getSelectionModel().getSelectedIndices().stream().mapToInt(Integer::intValue).toArray();List<Integer> selected=Arrays.stream(columns).boxed().toList();int[] end=endogenous.getSelectionModel().getSelectedIndices().stream().mapToInt(column->{int local=selected.indexOf(column);if(local<0)throw new IllegalArgumentException("Every endogenous variable must be a selected predictor.");return local;}).toArray();var model=new CopulaRegression.Model(Arrays.stream(columns).mapToObj(names::get).toList(),end,method.getValue(),position.getValue());var boot=new Bootstrap.Options(Integer.parseInt(samples.getText().trim()),Long.parseLong(seed.getText().trim()),Double.parseDouble(confidence.getText().trim()),interval.getValue(),RegressionBootstrap.Convention.STANDARD,true);var settings=new Settings(y,columns,model,boot);validate(settings,names);return settings;}
 static Optional<Settings> show(Window owner,List<String> names,Settings previous,boolean bootstrap){return new CopulaDialog(owner,names,previous,bootstrap).dialog.showAndWait();}
 static Settings smokeTest(Window owner,List<String> names){var probe=new CopulaDialog(owner,names,null,true);Button run=(Button)probe.dialog.getDialogPane().lookupButton(probe.dialog.getDialogPane().getButtonTypes().getFirst());javafx.application.Platform.runLater(()->{try{probe.endogenous.getSelectionModel().clearSelection();run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Missing endogenous selection accepted");probe.endogenous.getSelectionModel().select(0);probe.samples.setText("29");run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Invalid copula bootstrap attempts accepted");probe.samples.setText("80");probe.confidence.setText("1");run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Invalid copula confidence accepted");probe.confidence.setText(".95");run.fire();}catch(Throwable error){probe.dialog.close();throw error;}});return probe.dialog.showAndWait().orElseThrow(()->new AssertionError("Copula dialog did not accept valid input"));}
}
